// Complete the Bun docs MDX tree with every page bun.com publishes that the docs tree lacks.
// Inputs read live: https://bun.com/sitemap.xml and https://bun.com/llms.txt. A page counts as present when
// docs/<path>.mdx, docs/<path>.md or docs/<path>/index.mdx exists. Missing pages are fetched as Markdown
// (`<url>.md`, served with front matter for docs and blog posts) and written to docs/<path>.mdx.
// Pages without a Markdown source are reported, not scraped: /reference/* is generated by bun.com from the
// TypeScript definitions (packages/bun-types in the fork; apps/bun-m3/gen/api.ts reads them directly).
//
//   bun gen/site-complete.ts [--docs <fork>/docs] [--site https://bun.com] [--write] [--concurrency 4]
import { existsSync, mkdirSync } from "node:fs";
import { dirname, join } from "node:path";
import { parseArgs } from "node:util";

const { values: a } = parseArgs({
  options: {
    docs: { type: "string", default: join(import.meta.dir, "../../../.cache/bun-fork/docs") },
    site: { type: "string", default: "https://bun.com" },
    write: { type: "boolean", default: false },
    concurrency: { type: "string", default: "4" },
  },
});
const site = a.site!.replace(/\/$/, "");
const get = async (u: string) => {
  const r = await fetch(u, { signal: AbortSignal.timeout(30_000), redirect: "follow" });
  return { ok: r.ok, status: r.status, type: r.headers.get("content-type") ?? "", text: r.ok ? await r.text() : "" };
};

const sitemap = (await get(`${site}/sitemap.xml`)).text;
const paths = [...new Set([...sitemap.matchAll(/<loc>([^<]+)<\/loc>/g)].map((m) => new URL(m[1]!.trim()).pathname.replace(/^\/|\/$/g, "")))].filter(Boolean);
const llms = (await get(`${site}/llms.txt`)).text;
const llmsPaths = [...llms.matchAll(/\]\((https?:\/\/[^)\s]+)\)/g)].map((m) => new URL(m[1]!).pathname.replace(/^\/|\.md$/g, ""));

/** Path of the docs tree for a site path: /docs/x lives at docs/x, every other section keeps its prefix. */
const local = (p: string) => (p.startsWith("docs/") ? p.slice(5) : p === "docs" ? "index" : p);
const present = (p: string) => {
  const l = local(p);
  return [`${l}.mdx`, `${l}.md`, `${l}/index.mdx`, `${l}/index.md`].some((f) => existsSync(join(a.docs!, f)));
};

// /reference/* is generated from the TypeScript definitions; site files and the 404 page are not documents.
const generated = (p: string) => p.startsWith("reference/") || /\.(txt|xml|json)$/.test(p) || p === "404";
const missing = paths.filter((p) => !present(p) && !generated(p));
const report = { sitemap: paths.length, llms: llmsPaths.length, generated: paths.filter(generated).length, missing: missing.length, written: 0, noMarkdown: [] as string[], brokenLlms: [] as string[], truncatedSitemap: [] as string[], deadSitemap: [] as string[], aliases: [] as string[] };

const toFetch = missing;
// A sitemap entry that has no page and is a strict prefix of a sibling entry is a truncated URL upstream.
const truncated = (p: string) => paths.some((q) => q !== p && q.startsWith(p) && dirname(q) === dirname(p));

let i = 0;
async function worker() {
  while (i < toFetch.length) {
    const p = toFetch[i++]!;
    const r = await get(`${site}/${p}.md`);
    if (!r.ok || !r.type.includes("markdown")) {
      if (!r.ok && truncated(p)) report.truncatedSitemap.push(p);
      else {
        // the HTML page itself: a 404 there means the sitemap lists a page bun.com no longer serves
        const page = await get(`${site}/${p}`);
        const canonical = /<link[^>]*rel="canonical"[^>]*href="([^"]+)"/.exec(page.text)?.[1];
        const alias = canonical ? new URL(canonical).pathname.replace(/^\/|\/$/g, "") : "";
        if (page.status === 404) report.deadSitemap.push(p);
        else if (alias && alias !== p && (present(alias) || paths.includes(alias))) report.aliases.push(`${p} -> ${alias}`);
        else report.noMarkdown.push(`${p} (${r.status} ${r.type.split(";")[0]})`);
      }
      continue;
    }
    if (a.write) {
      const f = join(a.docs!, `${local(p)}.mdx`);
      mkdirSync(dirname(f), { recursive: true });
      await Bun.write(f, r.text.endsWith("\n") ? r.text : `${r.text}\n`);
    }
    report.written++;
  }
}
await Promise.all(Array.from({ length: Number(a.concurrency) }, worker));

for (const p of new Set(llmsPaths)) {
  if (present(p)) continue;
  const r = await get(`${site}/${p}`);
  if (!r.ok) report.brokenLlms.push(`${p} (${r.status})`);
}
report.noMarkdown.sort();
report.truncatedSitemap.sort();
report.deadSitemap.sort();
console.log(JSON.stringify(report, null, 1));
